  tank(k) { k.group(0, -0.05, 0, { rz: (k.rnd() - 0.5) * 0.2 }, () => { k.box(0.95, 0.2, 0.55, 0, 0.04, 0, C.olive, { metal: true }); for (const s of [-1, 1]) k.box(1.05, 0.16, 0.14, 0, 0, s * 0.3, C.soot); k.box(0.45, 0.16, 0.38, -0.05, 0.24, 0, C.olive, { metal: true, ry: 0.5 }); k.cyl(0.035, 0.035, 0.75, 0.2, 0.32, 0.2, C.steel, { n: 6, rz: Math.PI / 2 - 0.1, ry: 0.5, metal: true }); }); k.cap(-0.1, 0.4, 0, 0.3); k.ground(0.7, 3); },
  pylon(k) { const br = k.rnd() < 0.55; k.group(0, 0, 0, { rz: br ? 0.55 + k.rnd() * 0.5 : (k.rnd() - 0.5) * 0.15 }, () => { for (const [sx, sz] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) k.beam([sx * 0.35, 0, sz * 0.35], [sx * 0.06, 3.0, sz * 0.06], 0.045, C.rust, { metal: true }); for (let i = 0; i < 5; i++) { const t = i / 5, r = 0.35 - t * 0.29; k.beam([-r, t * 3, r], [r, t * 3 + 0.6, r], 0.025, C.steel, { metal: true }); k.beam([r, t * 3, -r], [-r, t * 3 + 0.6, -r], 0.025, C.steel, { metal: true }); } k.box(1.5, 0.05, 0.05, 0, 2.4, 0, C.rust, { metal: true }); k.box(1.0, 0.05, 0.05, 0, 2.85, 0, C.rust, { metal: true }); }); k.ground(0.7, 2); },
  lamp(k) { k.group(0, 0, 0, { rz: (k.rnd() - 0.3) * 0.6 }, () => { k.cyl(0.03, 0.04, 1.3, 0, 0, 0, C.steel, { n: 6, metal: true }); k.box(0.36, 0.04, 0.05, 0.16, 1.28, 0, C.steel, { metal: true }); k.box(0.14, 0.05, 0.08, 0.32, 1.23, 0, C.conc3); }); if (k.rnd() < 0.5) k.group(0.5, 0, 0.2, { rz: 0.1 }, () => { k.cyl(0.03, 0.03, 0.9, 0, 0, 0, C.steel, { n: 6, metal: true }); k.box(0.34, 0.34, 0.03, 0, 0.75, 0, k.rnd() < 0.5 ? C.blue : C.red, { metal: true }); }); },
  billboard(k) { k.group(0, 0, 0, { rz: (k.rnd() - 0.5) * 0.3 }, () => { for (const s of [-1, 1]) k.box(0.08, 1.5, 0.08, s * 0.6, 0, 0, C.rust, { metal: true }); k.box(1.7, 0.75, 0.05, 0, 1.3, 0, [C.blue, C.red, C.yellow, C.teal][Math.floor(k.rnd() * 4)], { metal: true }); k.box(0.7, 0.5, 0.06, 0.4, 1.4, 0.01, C.dark); k.beam([-0.6, 1.3, -0.03], [0.6, 2.05, -0.03], 0.03, C.rust, { metal: true }); }); k.cap(-0.4, 2.05, 0, 0.3); k.ground(0.8, 2); },
  container(k) { const n = 1 + Math.floor(k.rnd() * 3); for (let i = 0; i < n; i++) k.box(1.05, 0.42, 0.42, (k.rnd() - 0.5) * 0.4, i === 2 ? 0.42 : 0, i === 1 ? 0.5 : 0, [C.rust2, C.blue, C.red, C.teal, C.olive][Math.floor(k.rnd() * 5)], { metal: true, ry: (k.rnd() - 0.5) * 0.5, rz: i === 2 ? 0.2 : 0 }); k.ground(0.8, 2); },
  house(k) { const w = 1.0 + k.rnd() * 0.3; k.box(w, 0.7, 0.1, 0, 0, -0.45, C.conc3); k.box(0.1, 0.5 + k.rnd() * 0.3, 0.9, -w / 2, 0, 0, C.conc); k.box(0.1, 0.3, 0.5, w / 2, 0, -0.2, C.conc3); k.box(w * 0.9, 0.06, 0.6, 0, 0.5, -0.1, C.brick, { rx: 0.5 }); k.box(0.2, 0.9, 0.2, w * 0.3, 0, -0.35, C.brick); k.box(0.26, 0.26, 0.02, -0.2, 0.3, -0.39, C.dark); k.rubble(4, 0.9, C.conc2, 0.18); k.ground(0.9, 3); k.cap(0, 0.6, -0.4, 0.35); },
  turbine(k) { const br = k.rnd() < 0.5; k.cyl(0.05, 0.1, br ? 1.6 : 3.4, 0, 0, 0, C.white, { n: 8, metal: true }); if (br) k.group(0.5, 0.06, 0.3, { rz: -1.5, ry: 0.5 }, () => { k.cyl(0.05, 0.06, 1.8, 0, 0, 0, C.white, { n: 8, metal: true }); k.box(0.2, 0.2, 0.4, 0, 1.8, 0, C.white, { metal: true }); k.box(0.1, 1.3, 0.03, 0, 2.3, 0.25, C.conc3, { metal: true }); }); else { k.box(0.2, 0.2, 0.45, 0, 3.35, 0, C.white, { metal: true }); for (let a = 0; a < 2; a++) k.box(0.1, 1.4, 0.03, Math.sin(a * 2.1 + 0.5) * 0.7, 3.45 + Math.cos(a * 2.1 + 0.5) * 0.7 - 0.7, 0.25, C.conc3, { rz: -(a * 2.1 + 0.5), metal: true }); } k.ground(0.6, 2); },
  plane(k) { k.group(0, 0.02, 0, { rz: 0.12 + k.rnd() * 0.1, ry: 0 }, () => plane(k, 1.1 + k.rnd() * 0.3)); k.rubble(4, 1.4, C.conc3, 0.16); k.ground(1.3, 4); },
  antenna(k) { k.group(0, 0, 0, { rz: (k.rnd() - 0.5) * 0.3 }, () => { for (let a = 0; a < 3; a++) k.beam([Math.cos(a * 2.1) * 0.22, 0, Math.sin(a * 2.1) * 0.22], [0, 3.6, 0], 0.04, a ? C.red : C.white, { metal: true }); for (let i = 1; i < 6; i++) k.ring(0.22 * (1 - i / 6.4), 0, i * 0.6, 0, C.rust, { rx: Math.PI / 2, n: 6, metal: true }); k.hemi(0.3, 0.12, 2.2, 0, C.white, { rz: -1.3, sy: 0.4, n: 8, metal: true }); }); k.box(0.6, 0.4, 0.5, 0.5, 0, 0.3, C.conc); k.ground(0.7, 2); },
  pipe(k) { k.cyl(0.2, 0.2, 2.2, 0, 0.2, 0, C.rust2, { n: 8, rz: Math.PI / 2, metal: true }); k.cyl(0.2, 0.2, 1.0, 1.5, 0.1, 0.5, C.rust, { n: 8, rz: Math.PI / 2 - 0.3, ry: 0.6, metal: true }); for (const x of [-0.8, 0.5]) k.box(0.12, 0.3, 0.5, x, 0, 0, C.conc2); k.cyl(0.5, 0.5, 0.7, -1.4, 0, 0.3, C.steel, { n: 10, metal: true }); k.ground(0.9, 3); },
  wreck(k) { k.group(0, -0.35, 0, { rz: 0.22 + k.rnd() * 0.25, rx: (k.rnd() - 0.5) * 0.2 }, () => ship(k, 3.0 + k.rnd(), 0.75, k.rnd() < 0.4)); },
  wreck_small(k) { k.group(0, -0.25, 0, { rz: 0.5 + k.rnd() * 0.5 }, () => { k.box(1.3, 0.3, 0.42, 0, 0, 0, k.rnd() < 0.5 ? C.white : C.blue, { metal: true }); k.box(0.4, 0.3, 0.3, -0.2, 0.3, 0, C.conc3); k.beam([0.2, 0.3, 0], [0.3, 1.5, 0], 0.03, C.rust, { metal: true }); }); },
